static void skip_ws(const char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') { (*p)++; }
}

static char *parse_str(const char **p) {
    (*p)++;
    const char *start = *p;
    while (**p && **p != '"') {
        if (**p == '\\' && *(*p + 1)) (*p) += 2;
        else (*p)++;
    }
    size_t len = *p - start;
    char *str = malloc(len + 1);
    char *dst = str;
    const char *src = start;
    while (src < *p) {
        if (*src == '\\') {
            src++;
            if (*src == 'n') *dst++ = '\n';
            else if (*src == 't') *dst++ = '\t';
            else if (*src == 'r') *dst++ = '\r';
            else if (*src == 'b') *dst++ = '\b';
            else if (*src == 'f') *dst++ = '\f';
            else *dst++ = *src;
            src++;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
    if (**p == '"') (*p)++;
    return str;
}

json_node *parse_value(const char **p) {
    skip_ws(p);
    if (!**p) return NULL;
    json_node *node = calloc(1, sizeof(json_node));
    if (!node) return NULL;

    if (**p == 'n') { node->type = JSON_NULL; *p += 4; }
    else if (**p == 't') { node->type = JSON_BOOL; node->value.boolean = true; *p += 4; }
    else if (**p == 'f') { node->type = JSON_BOOL; node->value.boolean = false; *p += 5; }
    else if (**p == '"') { node->type = JSON_STRING; node->value.string = parse_str(p); }
    else if (**p == '[') {
        node->type = JSON_ARRAY; (*p)++; skip_ws(p);
        if (**p != ']') {
            while (**p) {
                json_node *elem = parse_value(p);
                if (node->value.array.count >= node->value.array.capacity) {
                    node->value.array.capacity = node->value.array.capacity == 0 ? 4 : node->value.array.capacity * 2;
                    node->value.array.elements = realloc(node->value.array.elements, node->value.array.capacity * sizeof(json_node*));
                }
                node->value.array.elements[node->value.array.count++] = elem;
                skip_ws(p);
                if (**p == ',') { (*p)++; skip_ws(p); }
                else break;
            }
        }
        if (**p == ']') (*p)++;
    } else if (**p == '{') {
        node->type = JSON_OBJECT; (*p)++; skip_ws(p);
        if (**p != '}') {
            while (**p) {
                if (**p == '"') {
                    char *key = parse_str(p);
                    skip_ws(p);
                    if (**p == ':') (*p)++;
                    skip_ws(p);
                    json_node *val = parse_value(p);
                    if (node->value.object.count >= node->value.object.capacity) {
                        node->value.object.capacity = node->value.object.capacity == 0 ? 4 : node->value.object.capacity * 2;
                        node->value.object.keys = realloc(node->value.object.keys, node->value.object.capacity * sizeof(char*));
                        node->value.object.values = realloc(node->value.object.values, node->value.object.capacity * sizeof(json_node*));
                    }
                    node->value.object.keys[node->value.object.count] = key;
                    node->value.object.values[node->value.object.count] = val;
                    node->value.object.count++;
                }
                skip_ws(p);
                if (**p == ',') { (*p)++; skip_ws(p); }
                else break;
            }
        }
        if (**p == '}') (*p)++;
    } else {
        node->type = JSON_NUMBER;
        char *end;
        node->value.number = strtod(*p, &end);
        *p = end;
    }
    return node;
}

json_node *parse_json(const char *json) {
    if (!json) return NULL;
    const char *p = json;
    return parse_value(&p);
}

void free_json(json_node *node) {
    if (!node) return;
    if (node->type == JSON_STRING) {
        free(node->value.string);
    } else if (node->type == JSON_ARRAY) {
        for (size_t i = 0; i < node->value.array.count; i++) {
            free_json(node->value.array.elements[i]);
        }
        free(node->value.array.elements);
    } else if (node->type == JSON_OBJECT) {
        for (size_t i = 0; i < node->value.object.count; i++) {
            free(node->value.object.keys[i]);
            free_json(node->value.object.values[i]);
        }
        free(node->value.object.keys);
        free(node->value.object.values);
    }
    free(node);
}

